 const dialog=useRef<HTMLDialogElement>(null),generation=useRef(0),adapterRef=useRef<ReturnType<typeof createThreeAdapter>|null>(null),[preview,setPreview]=useState<Project|null>(null),[adapter,setAdapter]=useState<ReturnType<typeof createThreeAdapter>|null>(null),[ops,setOps]=useState<Operation[]>([]),[nodeId,setNodeId]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[saving,setSaving]=useState(false),[revision,setRevision]=useState(project.revision),[name,setName]=useState(''),[count,setCount]=useState(0),[animate,setAnimate]=useState(true);
