import{useEffect,useRef,useState}from'react';import{api}from'./api.ts';import{Icon}from'./Icon.tsx';import{SetupFields,setupDraft,parseSetup}from'./NewProject.tsx';import{readPreferences,savePreferences,type Preferences}from'./preferences.ts';import type{Project}from'../../domain/schema.ts';import type{Operation}from'../../domain/operations.ts';
export type StudioDialogMode='settings'|'help'|'parameters'|'history';
export function StudioDialog({mode,project,onClose,onPreferences,onCommit}:{mode:StudioDialogMode;project:Project|null;onClose:()=>void;onPreferences:(prefs:Preferences)=>void;onCommit:(label:string,ops:Operation[],revision?:number)=>Promise<boolean>}){
 const dialog=useRef<HTMLDialogElement>(null),[tab,setTab]=useState(mode==='settings'?'general':'start'),[prefs,setPrefs]=useState(readPreferences),[draft,setDraft]=useState(()=>setupDraft(readPreferences().newProject)),[error,setError]=useState(''),[saved,setSaved]=useState(false),[info,setInfo]=useState<Awaited<ReturnType<typeof api.workspace>>|null>(null),[ai,setAI]=useState<Awaited<ReturnType<typeof api.aiStatus>>|null>(null),[events,setEvents]=useState<Array<Record<string,unknown>>>([]),[title,setTitle]=useState(project?.title??''),[baseRevision]=useState(project?.revision),[saving,setSaving]=useState(false);
 async function refresh(){setError('');try{const[workspace,provider]=await Promise.all([api.workspace(),api.aiStatus()]);setInfo(workspace);setAI(provider)}catch(e){setError((e as Error).message)}}
 useEffect(()=>{dialog.current?.showModal();if(mode==='settings')void refresh();if(mode==='history'&&project)void api.journal(project.id).then(j=>setEvents(j.reverse())).catch(e=>setError(e.message))},[]);
 function applyPrefs(){try{const value=savePreferences({...prefs,newProject:parseSetup(draft)});setPrefs(value);onPreferences(value);setSaved(true);setError('')}catch(e){setError((e as Error).message)}}
 async function rename(){if(!project||saving)return;setSaving(true);try{const clean=title.trim();if(!clean||clean.length>200)throw Error('Проверьте название проекта.');if(await onCommit('Переименовать проект',[{op:'updateProjectMeta',values:{title:clean}}],baseRevision))onClose();else setError('Изменение не сохранено. Проверьте сообщение студии.')}catch(e){setError((e as Error).message)}finally{setSaving(false)}}
 const tabs=mode==='settings'?[['general','Просмотр'],['defaults','Новые проекты'],['ai','ИИ'],['storage','Хранилище']]:[['start','Быстрый старт'],['keys','Клавиши'],['about','О программе']];
 return <dialog ref={dialog} className={'workspace-dialog studio-dialog '+(mode==='parameters'?'project-parameters-dialog':'')} aria-labelledby="studio-dialog-title" onCancel={e=>{e.preventDefault();if(!saving)onClose()}}><header><div><span className="eyebrow">MOTIVELIUM</span><h2 id="studio-dialog-title">{{settings:'Настройки студии',help:'Справка',parameters:'Параметры проекта',history:'История изменений'}[mode]}</h2></div><button className="icon-button" aria-label="Закрыть окно студии" disabled={saving} onClick={onClose}><Icon name="close"/></button></header>
 {(mode==='settings'||mode==='help')&&<nav className="studio-dialog-tabs" aria-label="Разделы окна">{tabs.map(([id,label])=><button key={id} className={tab===id?'current':''} aria-pressed={tab===id} onClick={()=>setTab(id!)}>{label}</button>)}</nav>}
 <div className="workspace-dialog-body">
 {mode==='settings'&&<>
  {tab==='general'&&<section><h3>Предпросмотр</h3><label className="setting-check"><input type="checkbox" aria-label="Автозапуск превью в галереях" checked={prefs.animatePreviews} onChange={e=>{setPrefs({...prefs,animatePreviews:e.target.checked});setSaved(false)}}/>Автоматически проигрывать превью в галереях</label><p className="dialog-note">Применяется при следующем открытии галереи. На экспорт и анимацию ролика не влияет.</p></section>}
  {tab==='defaults'&&<section><h3>Начальные параметры</h3><p className="dialog-note">Используются только при создании нового пустого проекта.</p><SetupFields title={false} draft={draft} onChange={value=>{setDraft(value);setSaved(false)}}/></section>}
  {tab==='ai'&&<section><h3>Подключение ИИ</h3><p className={'connection-state '+(ai?.ready?'ready':'')}>{ai?ai.ready?'Подключение настроено':'Подключение не настроено':'Загрузка состояния…'}</p>{ai&&<dl className="workspace-spec"><div><dt>Профиль</dt><dd>{ai.label}</dd></div><div><dt>Правки</dt><dd>{ai.model}</dd></div><div><dt>Кадры</dt><dd>{ai.visionModel??'Не задана'}</dd></div></dl>}{ai?.reason&&<p className="field-warning">{ai.reason}</p>}<p className="dialog-note">Подключение определяется профилем на сервере. Ключи в браузер не передаются. Без ИИ доступны ручные правки, эффекты и экспорт.</p><details className="connection-help"><summary>Как подключить свой профиль</summary><p>На компьютере, где запущена студия, настройте ключ подписки GLM через переменную окружения <code>MOTIVELIUM_GLM_KEY_FILE</code>. Модели задаются через <code>MOTIVELIUM_GLM_MODEL</code> и <code>MOTIVELIUM_GLM_VISION_MODEL</code>. После изменения окружения перезапустите сервер. Этот экран не изменяет профиль.</p></details><button className="secondary" onClick={()=>void refresh()}>Обновить состояние подключения</button></section>}
  {tab==='storage'&&<section><h3>Хранилище проектов</h3>{info?<dl className="workspace-spec"><div><dt>Проекты</dt><dd>{info.projects}</dd></div><div><dt>Файлы ресурсов</dt><dd>{info.assets}</dd></div><div><dt>Объём ресурсов</dt><dd>{(info.assetBytes/1024/1024).toFixed(1)} МБ</dd></div><div><dt>Импорт изображений и музыки</dt><dd>{info.media.ready?'Готов':info.media.reason}</dd></div></dl>:<p>Загрузка сведений…</p>}<p className="dialog-note">В проектах сохраняются исходные файлы, сцены и история. Для переноса используйте «Файл → Скачать проект».</p><button className="secondary" onClick={()=>void refresh()}>Обновить сведения</button></section>}
 </>}
 {mode==='parameters'&&project&&<section><label>Название<input aria-label="Название текущего проекта" autoFocus value={title} maxLength={200} disabled={saving} onChange={e=>setTitle(e.target.value)}/></label><dl className="workspace-spec"><div><dt>Размер кадра</dt><dd>{project.size.width} × {project.size.height} px</dd></div><div><dt>Частота</dt><dd>{(project.fps.num/project.fps.den).toFixed(2).replace(/\.00$/,'')} кадров/с</dd></div><div><dt>Длительность</dt><dd>{(project.durationFrames*project.fps.den/project.fps.num).toFixed(2)} с · {project.durationFrames} кадров</dd></div><div><dt>Сцены / слои</dt><dd>{project.sequences.length} / {project.nodes.length}</dd></div></dl><p className="dialog-note">Название можно изменить с отменой. Размер, частота и длительность текущего ролика пока доступны для просмотра; они выбираются при создании проекта.</p>{baseRevision!==project.revision&&<p className="field-warning">Проект изменился. Откройте параметры заново перед сохранением.</p>}</section>}
 {mode==='help'&&<>
  {tab==='start'&&<section className="help-article"><h3>От проекта к ролику</h3><ol><li>Создайте новый проект: выберите формат, частоту и длительность.</li><li>Откройте «Ресурсы», загрузите изображение и нажмите «Добавить в сцену».</li><li>Добавьте текст в панели «Слои». Перемещайте объекты на холсте, меняйте размер за углы.</li><li>Поставьте ключи на разных кадрах или примеряйте эффекты из галереи. Изменение можно отменить.</li><li>Загрузите WAV или MP3. Выберите «Сделать музыкой», настройте громкость и смещение.</li><li>Откройте «Экспорт → Видео MP4». Для передачи редактируемого проекта используйте «Файл → Скачать проект».</li></ol><h3>Модели и ИИ</h3><p>Модель GLB/GLTF добавляется через «Файл» или панель ресурсов. Выберите слой модели и откройте «Детали и камера 3D» в свойствах. Для ИИ-правки сначала выберите объект; результат сохраняется только после применения.</p></section>}
  {tab==='keys'&&<section><h3>Сочетания клавиш</h3><dl className="workspace-spec"><div><dt><kbd>Пробел</kbd></dt><dd>Просмотр / пауза</dd></div><div><dt><kbd>←</kbd> <kbd>→</kbd></dt><dd>Один кадр назад / вперёд</dd></div><div><dt><kbd>Ctrl + Z</kbd></dt><dd>Отменить</dd></div><div><dt><kbd>Ctrl + Shift + Z</kbd></dt><dd>Повторить</dd></div><div><dt><kbd>Shift</kbd> при изменении размера</dt><dd>Сохранить пропорции</dd></div><div><dt><kbd>Esc</kbd></dt><dd>Отменить перетаскивание / закрыть окно</dd></div></dl><p className="dialog-note">В текстовых полях работают обычные клавиши редактирования. Открытые окна не перематывают основной ролик.</p></section>}
  {tab==='about'&&<section><h3>Motivelium</h3><p>Локальная студия программного видео. Версия 0.1.0-alpha.3.</p><p className="dialog-note">Проекты хранятся на компьютере, где запущен сервер. При переносе ZIP включает текущее состояние и ресурсы; история отмен и готовые MP4 остаются в исходной студии.</p><h3>Замечания</h3><p className="dialog-note">Для описания проблемы укажите название проекта, версию, номер кадра и действие. Прикладывайте кадр по своему выбору. Автоматическая отправка замечаний не выполняется.</p><h3>Сторонние материалы</h3><p className="dialog-note">Собственный код — MIT. Полные условия и авторство сторонних компонентов: LICENSE, THIRD_PARTY.md и папка licenses в комплекте программы. Публичный выпуск этого кандидата пока не объявлен.</p></section>}
 </>}
 {mode==='history'&&<section><p className="dialog-note">Последние действия проекта. Отмена и повтор доступны в верхней панели; журнал может содержать технические события восстановления.</p><ol className="project-history">{events.filter(e=>e.description||['undo','redo','init'].includes(String(e.kind))).map((e,i)=><li key={i}><strong>{String(e.description??({undo:'Отмена изменения',redo:'Повтор изменения',init:'Создание проекта'}[String(e.kind)]??e.kind))}</strong><span>Версия {String(e.revision)} · {e.at?new Date(String(e.at)).toLocaleString('ru-RU'):''}</span></li>)}</ol>{!events.length&&<p className="dialog-note">Действий пока нет.</p>}</section>}
 {error&&<p role="alert" className="field-warning">{error}</p>}{saved&&<p className="settings-saved" role="status">Настройки сохранены в этом браузере.</p>}
 </div><footer>{mode==='settings'&&(tab==='general'||tab==='defaults')&&<button className="primary" onClick={applyPrefs}>Сохранить настройки</button>}{mode==='parameters'&&project&&<button className="primary" disabled={saving||title.trim()===project.title||baseRevision!==project.revision} onClick={()=>void rename()}>{saving?'Сохранение…':'Сохранить название'}</button>}<button className="text-button" disabled={saving} onClick={onClose}>Закрыть</button></footer></dialog>;
}
