import {useState,type ReactNode} from 'react';import{TemplateGallery}from'./TemplateGallery.tsx';
import type {ProjectSummary} from './api.ts';
import {CommandMenu} from './CommandMenu.tsx';import {Icon} from './Icon.tsx';
import {MATTER_PREFIX} from '../../domain/matter.ts';import {ENERGY_PREFIX} from '../../domain/energy.ts';import {SHOWCASE_PREFIX} from '../../domain/showcase.ts';
export type HomeSection='projects'|'templates'|'examples';
export function ProjectHome({brand,projects,loading,opening,notice,onOpen,onNew,onImport,onDemo,section,onSection,onSettings,onHelp,onAction,onDownload,onTemplateCreated,children}:{brand:ReactNode;projects:ProjectSummary[];loading:boolean;opening:boolean;notice:ReactNode;onOpen:(id:string)=>void;onNew:()=>void;onImport:()=>void;onDemo:(energy?:boolean,matter?:boolean)=>void;section:HomeSection;onSection:(s:HomeSection)=>void;onSettings:()=>void;onHelp:()=>void;onAction:(kind:'rename'|'copy',p:ProjectSummary)=>void;onDownload:(id:string)=>void;onTemplateCreated:(id:string,frame:number)=>Promise<void>;children:ReactNode}){
 const [query,setQuery]=useState('');const filtered=projects.filter(p=>p.title.toLocaleLowerCase('ru').includes(query.trim().toLocaleLowerCase('ru'))).sort((a,b)=>a.title.localeCompare(b.title,'ru'));
 return <div className="project-home workspace-home"><aside className="home-sidebar"><div className="home-brand">{brand}</div><nav aria-label="Разделы студии">{([['projects','folder','Проекты'],['templates','layers','Шаблоны'],['examples','play','Примеры']] as const).map(([id,icon,label])=><button key={id} aria-current={section===id?'page':undefined} disabled={opening} onClick={()=>onSection(id)}><Icon name={icon}/><span>{label}</span></button>)}</nav><nav className="home-service" aria-label="Служебные разделы"><button aria-label="Настройки" title="Настройки" onClick={onSettings} disabled={opening}><Icon name="settings"/><span>Настройки</span></button><button aria-label="Справка" title="Справка" onClick={onHelp} disabled={opening}><Icon name="help"/><span>Справка</span></button><small><i className="live-dot"/>Локальная студия</small></nav></aside><main className="home-content">
 <div className="project-shelf-heading"><div><span className="eyebrow">MOTIVELIUM / СТУДИЯ</span><h1>{{projects:'Проекты',templates:'Шаблоны',examples:'Примеры'}[section]} {section==='projects'&&<small>{loading?'…':projects.length}</small>}</h1><p>{{projects:'Продолжите работу или начните с пустой сцены.',templates:'Заготовки для новых роликов.',examples:'Готовые ролики, которые можно разобрать и изменить.'}[section]}</p></div><div className="shelf-actions"><button className="text-button" disabled={opening} onClick={onImport}><Icon name="folder" size={17}/>Импортировать</button><button className="primary" disabled={opening} onClick={onNew}><Icon name="plus" size={17}/>Новый проект</button></div></div>{notice}
 {section==='projects'&&<><div className="project-shelf-tools"><label className="project-search"><Icon name="search" size={17}/><input type="search" aria-label="Поиск проектов" placeholder="Поиск проектов" value={query} onChange={e=>setQuery(e.target.value)}/></label><span className="project-sort">По названию</span></div>{loading?<p className="loading" role="status">Загружаются проекты…</p>:filtered.length?<div className="project-grid">{filtered.map((p,i)=>{const matter=p.id.startsWith(MATTER_PREFIX+'-'),energy=p.id.startsWith(ENERGY_PREFIX+'-'),showcase=p.id.startsWith(SHOWCASE_PREFIX+'-');return <article className="project-card has-actions" key={p.id}><CommandMenu appearance="more" label={'Действия с проектом '+p.title} disabled={opening} commands={[{label:'Переименовать…',icon:'text',action:()=>onAction('rename',p)},{label:'Создать копию…',icon:'layers',action:()=>onAction('copy',p)},{label:'Скачать проект…',hint:'ZIP со всеми ресурсами',icon:'download',divider:true,action:()=>onDownload(p.id)}]}/><button className="project-open" aria-label={'Открыть проект '+p.title} onClick={()=>onOpen(p.id)} disabled={opening}><div className={'project-art '+(matter?'matter-art':energy?'energy-art':showcase?'showcase-art':'art-'+i%3)}>{matter&&<div className="matter-cover"><i/><i/><b>МАТЕРИЯ.</b></div>}{energy&&<div className="energy-cover"><i/><b>РАЗРЯД.</b></div>}{showcase&&<img src="/showcase/assets/kinetic-sculpture.png" alt=""/>}<span>{String(i+1).padStart(2,'0')}</span>{!matter&&!energy&&!showcase&&<div className="art-shape"/>}<small>{matter||energy||showcase?'ДЕМОПРОЕКТ':'ПРОЕКТ'}</small></div><div className="project-card-info"><h3>{p.title}</h3><p><span>{p.updatedAt?new Date(p.updatedAt).toLocaleDateString('ru-RU'):''}</span><span>Версия {p.revision}</span></p><Icon name="arrow" size={18}/></div></button></article>})}</div>:<div className="shelf-empty"><Icon name="folder" size={30}/><h2>{query?'Проекты не найдены':'Пока нет проектов'}</h2><p>{query?'Измените запрос или очистите поиск.':'Создайте проект, импортируйте ZIP или откройте пример.'}</p>{query&&<button className="text-button" onClick={()=>setQuery('')}>Очистить поиск</button>}</div>}</>}
 {section==='examples'&&<div className="example-grid">{[['Обзор возможностей','Камера, анимация и типографика','showcase'],['Разряд','Свет, частицы и графические акценты','energy'],['Материя','Потоки, контуры и устройство в 3D','matter']].map(([title,description,kind],i)=><article className="example-card" key={kind}><div className={'example-cover example-'+kind}><span>0{i+1}</span><b>{title}</b><Icon name={i===2?'cube':i===1?'bolt':'motion'} size={64}/></div><div><p>{description}</p><button className="text-button" disabled={opening} onClick={()=>onDemo(i===1,i===2)}>Создать свою копию<Icon name="arrow" size={16}/></button></div></article>)}</div>}
 {section==='templates'&&<TemplateGallery disabled={opening} onCreated={onTemplateCreated}/>}
 </main>{children}</div>;
}
